from pwn import remote
import time

HOST = "crypto.chal.csaw.io"
PORT = 8000
NUM_SAMPLES = 15
SAMPLES_FILE = "/home/ctfplayer/ctf_files/byte_me_samples.txt"

def get_sample():
    try:
        r = remote(HOST, PORT, timeout=5)
        data = r.recvline(timeout=5)
        r.close()
        if data is not None:
            return data.strip().decode()
    except Exception as e:
        return None
    return None

samples = []
for i in range(NUM_SAMPLES):
    sample = None
    retry = 0
    while sample is None and retry < 3:
        sample = get_sample()
        retry += 1
        time.sleep(0.2)
    if sample:
        samples.append(sample)
    else:
        samples.append("")

with open(SAMPLES_FILE, "w") as f:
    for s in samples:
        f.write(s + "\n")

